import gleam/dynamic
import gleam/string
import gleam/list
import gleam/float
import gleam/result
import gleam/io
import gleam/json
import gleam/dict.{type Dict}

pub type Vocab {
  Vocab(mapping: Dict(String, Int), reverse: Dict(Int, String))
}

pub type Token {
  Token(id: Int, embedding: List(Float))
}

const dim = 9216

pub fn load_vocab(path: String) -> Result(Vocab, String) {
  case simplifile.read(path) {
    Ok(content) -> {
      case json.decode(content, dynamic.dict(dynamic.string, dynamic.int)) {
        Ok(mapping) -> {
          let reverse = dict.fold(mapping, dict.new(), fn(acc, key, value) {
            dict.insert(acc, value, key)
          })
          Ok(Vocab(mapping: mapping, reverse: reverse))
        }
        Error(_) -> Error("Failed to decode vocab JSON")
      }
    }
    Error(_) -> Error("Failed to read vocab file")
  }
}

pub fn tokenize(vocab: Vocab, text: String) -> List(Int) {
  let normalized = normalize_text(text)
  normalized
  |> string.to_graphemes
  |> list.map(fn(grapheme) {
    dict.get(vocab.mapping, grapheme) |> result.unwrap(3)
  })
}

pub fn detokenize(vocab: Vocab, ids: List(Int)) -> String {
  ids
  |> list.map(fn(id) { dict.get(vocab.reverse, id) |> result.unwrap("?") })
  |> string.concat
}

fn normalize_text(text: String) -> String {
  text
  |> string.lowercase
  |> string.replace("-", " ")
  |> string.replace("  ", " ")
  |> string.trim
}

fn lorenz_embedding(id: Int, index: Int) -> List(Float) {
  let lorenz_params = [10.0, 28.0, 2.666666666666667]
  let planet_index = index % 3
  let sigma = case list.at(lorenz_params, planet_index) {
    Ok(v) -> v
    Error(_) -> 10.0
  }
  let rho = case list.at(lorenz_params, { planet_index + 1 } % 3) {
    Ok(v) -> v
    Error(_) -> 28.0
  }
  let beta = case list.at(lorenz_params, { planet_index + 2 } % 3) {
    Ok(v) -> v
    Error(_) -> 2.666666666666667
  }
  let dt = 0.01
  let x0 = float.multiply(int.to_float(id), 0.1)
  let y0 = float.multiply(int.to_float(index), 2.0)
  let z0 = 0.0
  let x1 = float.add(x0, float.multiply(dt, float.multiply(sigma, float.subtract(y0, x0))))
  let y1 = float.add(y0, float.multiply(dt, float.subtract(float.multiply(x0, float.subtract(rho, z0)), y0)))
  let z1 = float.add(z0, float.multiply(dt, float.subtract(float.multiply(x0, y0), float.multiply(beta, z0))))
  let phase = float.multiply(float.multiply(float.sin(x1), float.cos(y1)), float.sin(z1))
  let sin_phase = float.sin(phase)
  let cos_phase = float.cos(phase)
  list.flatten([[phase, sin_phase, cos_phase, sigma, rho, beta, x1, y1, z1], list.repeat(0.0, dim - 9)])
}

fn b_spline_basis(x: Float, knots: List(Float), degree: Int) -> List(Float) {
  case degree {
    0 -> {
      list.index_map(knots, fn(i, k) {
        let next_knot = case list.at(knots, i + 1) {
          Ok(v) -> v
          Error(_) -> float.add(k, 1.0)
        }
        case float.compare(x, k) != order.Lt && float.compare(x, next_knot) == order.Lt {
          True -> 1.0
          False -> 0.0
        }
      })
    }
    _ -> {
      let prev_basis = b_spline_basis(x, knots, degree - 1)
      list.index_map(prev_basis, fn(i, b) {
        let k_i = case list.at(knots, i) {
          Ok(v) -> v
          Error(_) -> 0.0
        }
        let k_ipd = case list.at(knots, i + degree) {
          Ok(v) -> v
          Error(_) -> 1.0
        }
        let term1 = case float.compare(float.subtract(k_ipd, k_i), 0.0) != order.Eq {
          True -> float.multiply(float.divide(float.subtract(x, k_i), float.subtract(k_ipd, k_i)), b)
          False -> 0.0
        }
        let next_b = case list.at(prev_basis, i + 1) {
          Ok(v) -> v
          Error(_) -> 0.0
        }
        let k_ip1 = case list.at(knots, i + 1) {
          Ok(v) -> v
          Error(_) -> 0.0
        }
        let k_ipd1 = case list.at(knots, i + degree + 1) {
          Ok(v) -> v
          Error(_) -> 1.0
        }
        let term2 = case float.compare(float.subtract(k_ipd1, k_ip1), 0.0) != order.Eq {
          True -> float.multiply(float.divide(float.subtract(k_ipd1, x), float.subtract(k_ipd1, k_ip1)), next_b)
          False -> 0.0
        }
        float.add(term1, term2)
      })
    }
  }
}

fn kan_spline_eval(x: Float, coeffs: List(Float), grid: Int) -> Float {
  let knots = list.range(0, grid - 1) |> list.map(fn(i) { float.divide(int.to_float(i), int.to_float(grid - 1)) })
  let basis = b_spline_basis(x, knots, 3)
  list.zip(basis, coeffs) 
  |> list.map(fn(pair) { 
    let #(b, c) = pair
    float.multiply(b, c)
  }) 
  |> list.fold(0.0, fn(acc, val) { float.add(acc, val) })
}

pub fn hybrid_tokenize(vocab: Vocab, text: String, grid: Int, birth_degrees: List(Float)) -> List(Token) {
  let normalized = normalize_text(text)
  normalized
  |> string.to_graphemes
  |> list.index_map(fn(index, grapheme) {
    let id = dict.get(vocab.mapping, grapheme) |> result.unwrap(0)
    let lorenz_emb = lorenz_embedding(id, index)
    let planet_index = index % list.length(birth_degrees)
    let degree = case list.at(birth_degrees, planet_index) {
      Ok(v) -> v
      Error(_) -> 0.0
    }
    let phase_shift = float.sin(float.add(float.multiply(int.to_float(index), 0.1), degree))
    let lorenz_emb_shifted = list.map(lorenz_emb, fn(val) { float.add(val, phase_shift) })
    let spline_x = float.divide(int.to_float(index), int.to_float(string.length(text)))
    let coeffs = list.repeat(1.0, grid)
    let spline_val = kan_spline_eval(spline_x, coeffs, grid)
    let embedding = list.map(lorenz_emb_shifted, fn(val) { float.add(val, float.multiply(spline_val, 0.01)) })
    Token(id: id, embedding: embedding)
  })
}

pub fn main() {
  io.println("Hybrid Gleam Tokenizer Loaded for JAIDE V33 LLM")
}
