pub fn update_state(state: *NeuralState, token_embedding: []f64, grid_val: usize) void {
  var sum_emb: f64 = 0.0;
  for (token_embedding) |emb| {
    sum_emb += emb;
  }
  const factor = @as(f64, @floatFromInt(d_model * grid_val));
  state.potential += sum_emb * 0.01 * @log(factor);
  state.quantum_phase += math.pi / 180.0;
}

pub fn kan_spline_eval(x: f64, coeffs: []const f64, grid_val: usize, allocator: std.mem.Allocator) !f64 {
  var knots = try allocator.alloc(f64, grid_val);
  defer allocator.free(knots);
  for (0..grid_val) |i| {
    knots[i] = @as(f64, @floatFromInt(i)) / @as(f64, @floatFromInt(grid_val - 1));
  }
  var basis = try b_spline_basis(x, knots, 3, allocator);
  defer allocator.free(basis);
  var sum: f64 = 0.0;
  for (0..@min(basis.len, coeffs.len)) |i| {
    sum += basis[i] * coeffs[i];
  }
  return sum;
}

fn b_spline_basis(x: f64, knots: []const f64, degree: u32, allocator: std.mem.Allocator) ![]f64 {
  if (degree == 0) {
    var basis = try allocator.alloc(f64, knots.len - 1);
    for (0..knots.len - 1) |i| {
      basis[i] = if (x >= knots[i] and x < knots[i+1]) 1.0 else 0.0;
    }
    return basis;
  } else {
    var prev_basis = try b_spline_basis(x, knots, degree - 1, allocator);
    defer allocator.free(prev_basis);
    var basis = try allocator.alloc(f64, if (prev_basis.len > 0) prev_basis.len - 1 else 0);
    for (0..basis.len) |i| {
      var term1: f64 = 0.0;
      if (knots[i + degree] - knots[i] != 0.0) {
        term1 = (x - knots[i]) / (knots[i + degree] - knots[i]) * prev_basis[i];
      }
      var term2: f64 = 0.0;
      if (i + 1 < prev_basis.len and knots[i + degree + 1] - knots[i + 1] != 0.0) {
        term2 = (knots[i + degree + 1] - x) / (knots[i + degree + 1] - knots[i + 1]) * prev_basis[i + 1];
      }
      basis[i] = term1 + term2;
    }
    return basis;
  }
}

pub fn main() !void {
  var gpa = std.heap.GeneralPurposeAllocator(.{}){};
  defer _ = gpa.deinit();
  const allocator = gpa.allocator();

  var state: NeuralState = .{
    .potential = 0.0,
    .quantum_phase = 0.0,
    .lorenz_params = .{10.0, 28.0, 8.0/3.0},
    .spline_coeffs = undefined,
  };

  for (0..d_model) |i| {
    for (0..grid) |j| {
      state.spline_coeffs[i][j] = 0.0;
    }
  }

  var token_emb = try allocator.alloc(f64, d_model);
  defer allocator.free(token_emb);

  for (token_emb) |*val| {
    val.* = 0.0;
  }

  update_state(&state, token_emb, grid);
  std.debug.print("Quantum Zig Loaded for JAIDE V33\n", .{});
}
